	data     = map[string]fake{}  // so'rov -> tayyor natija
	fail     = map[string]error{} // so'rov -> xato ("open" — ulanishdagi xato)
	calls    []string             // bajarilgan buyruqlar jurnali
	lastID   int64
	prepares int   // nechta Prepare chaqirilgani
	affected int64 = 1
)

func init()                                           { sql.Register("fake", &fake{}) }
func (f *fake) Open(string) (driver.Conn, error)      { return &fake{}, fail["open"] }
func (f *fake) Prepare(q string) (driver.Stmt, error) { prepares++; return &fake{q: q}, nil }
func (f *fake) Close() error                          { return nil }
func (f *fake) NumInput() int                         { return -1 }
func (f *fake) Columns() []string                     { return f.cols }
func (f *fake) LastInsertId() (int64, error)          { return lastID, nil }
func (f *fake) RowsAffected() (int64, error)          { return affected, nil }
func (f *fake) Begin() (driver.Tx, error)             { calls = append(calls, "BEGIN"); return f, nil }
func (f *fake) Commit() error                         { calls = append(calls, "COMMIT"); return nil }
func (f *fake) Rollback() error                       { calls = append(calls, "ROLLBACK"); return nil }
func (f *fake) Exec(a []driver.Value) (driver.Result, error) {
	calls, lastID = append(calls, fmt.Sprintf("%s %v", f.q, a)), lastID+1
	return f, fail[f.q]
}
func (f *fake) Query(a []driver.Value) (driver.Rows, error) {
	r := data[f.q]
	calls = append(calls, fmt.Sprintf("%s %v", f.q, a))
	return &r, fail[f.q]
}
func (f *fake) Next(dest []driver.Value) error {
	if f.i == len(f.rows) {
		return cmp.Or(f.err, io.EOF)
	}
	copy(dest, f.rows[f.i])
	f.i++
	return nil
