// Soxta drayver (qisqa variant): faqat tayyor qatorlarni qaytaradi.
type fake struct {
	cols []string
	rows [][]driver.Value
	err  error // oxirgi qatordan keyin Next shu xatoni qaytaradi
	i    int
}

var data = map[string]fake{} // so'rov -> tayyor natija

func init()                                                { sql.Register("fake", &fake{}) }
func (f *fake) Open(string) (driver.Conn, error)           { return f, nil }
func (f *fake) Prepare(q string) (driver.Stmt, error)      { r := data[q]; return &r, nil }
func (f *fake) Close() error                               { return nil }
