	return nil
}

func countWrong(rows *sql.Rows) (int, error) {
	n := 0
	for rows.Next() {
		n++
	}
	return n, nil // rows.Err() tekshirilmagan!
}

func countRight(rows *sql.Rows) (int, error) {
	n := 0
	for rows.Next() {
		n++
	}
	return n, rows.Err()
}

func main() {
	db, _ := sql.Open("fake", "")
	q := "SELECT id FROM users"
	broken := fake{cols: []string{"id"}, rows: [][]driver.Value{{int64(1)}, {int64(2)}}, err: errors.New("timeout")}

	data[q] = broken
	rows, _ := db.Query(q)
	fmt.Println(countWrong(rows))
	rows, _ = db.Query(q)
	fmt.Println(countRight(rows))
}

