}

func (j *JSON[T]) Scan(src any) error {
	var b []byte
	switch x := src.(type) {
	case string:
		b = []byte(x)
	case []byte:
		b = x
	default:
		return fmt.Errorf("json: kutilmagan tur %T", src)
	}
	return json.Unmarshal(b, &j.V)
}

