func (f *fake) Prepare(q string) (driver.Stmt, error)      { r := data[q]; return &r, nil }
func (f *fake) Close() error                               { return nil }
func (f *fake) NumInput() int                              { return -1 }
func (f *fake) Columns() []string                          { return f.cols }
func (f *fake) Begin() (driver.Tx, error)                  { return nil, driver.ErrSkip }
func (f *fake) Exec([]driver.Value) (driver.Result, error) { return nil, driver.ErrSkip }
func (f *fake) Query([]driver.Value) (driver.Rows, error)  { return f, nil }
func (f *fake) Next(dest []driver.Value) error {
	if f.i == len(f.rows) {
		return cmp.Or(f.err, io.EOF)
	}
	copy(dest, f.rows[f.i])
	f.i++
	return nil
}

func Each[T any](rows *sql.Rows, scan func(*sql.Rows) (T, error)) iter.Seq2[T, error] {
	return func(yield func(T, error) bool) {
		defer rows.Close()
		for rows.Next() {
			v, err := scan(rows)
			if !yield(v, err) || err != nil {
				return
			}
		}
		if err := rows.Err(); err != nil {
			var zero T
			yield(zero, err)
		}
	}
}

func main() {
	db, _ := sql.Open("fake", "")
	q := "SELECT name FROM users"
	data[q] = fake{cols: []string{"name"}, rows: [][]driver.Value{{"Aziz"}, {"Dilnoza"}, {"Bobur"}}}

	rows, _ := db.Query(q)
	names := Each(rows, func(r *sql.Rows) (string, error) {
		var s string
		return s, r.Scan(&s)
	})
	for name, err := range names {
		fmt.Println(name, err)
	}
}

