	db, _ := sql.Open("fake", "")
	ctx := context.Background()
	fmt.Println("1:", transfer(ctx, db, 1, 2, 100))

	fail["UPDATE accounts SET balance = balance - ? WHERE id = ?"] = ErrInsufficient
	err := transfer(ctx, db, 1, 2, 5000)
	fmt.Println("2:", err, errors.Is(err, ErrInsufficient))
	fmt.Println(calls)
}

