import (
	"fmt"
	"strconv"
	"strings"
)

func valuesPG(rows, cols int) string {
	var groups []string
	n := 0
	for range rows {
		marks := make([]string, cols)
		for c := range marks {
			n++
			marks[c] = "$" + strconv.Itoa(n)
		}
		groups = append(groups, "("+strings.Join(marks, ", ")+")")
	}
	return strings.Join(groups, ", ")
}

func main() {
	fmt.Println("INSERT INTO products(name, price) VALUES", valuesPG(3, 2))
}

