import (
	"errors"
	"fmt"
)

type PgError struct{ Code string }

func (e *PgError) Error() string { return "SQLSTATE " + e.Code }

type MySQLError struct{ Number uint16 }

func (e *MySQLError) Error() string { return fmt.Sprintf("Error %d", e.Number) }

func retryable(err error) bool {
	var pg *PgError
	if errors.As(err, &pg) {
		return pg.Code == "40001" || pg.Code == "40P01"
	}
	var my *MySQLError
	if errors.As(err, &my) {
		return my.Number == 1213 || my.Number == 1205
	}
	return false
}

func main() {
	fmt.Println(retryable(fmt.Errorf("tx: %w", &PgError{"40001"})))
	fmt.Println(retryable(&PgError{"23505"})) // unique violation: qayta urinish foydasiz
	fmt.Println(retryable(&MySQLError{1213}))
	fmt.Println(retryable(errors.New("boshqa xato")))
}

