	return driver.RowsAffected(1), fail[f.q]
}

type PgError struct{ Code string }

func (e *PgError) Error() string { return "SQLSTATE " + e.Code }

func withRetry(max int, fn func() error) (err error) {
	for attempt := 1; attempt <= max; attempt++ {
		if err = fn(); err == nil {
			return nil
		}
		var pg *PgError
		if !errors.As(err, &pg) || pg.Code != "40001" {
			return err // qayta urinish foydasiz
		}
		time.Sleep(time.Duration(attempt) * time.Millisecond) // backoff
	}
	return fmt.Errorf("%d urinishdan keyin: %w", max, err)
}

func main() {
	db, _ := sql.Open("fake", "")
	q := "UPDATE counters SET n = n + 1 WHERE id = 1"
	fail[q] = &PgError{"40001"}

	attempts := 0
	err := withRetry(5, func() error {
		if attempts++; attempts == 3 {
			delete(fail, q) // 3-urinishda ziddiyat yo'qoladi
		}
		_, err := db.Exec(q)
		return err
	})
	fmt.Println("urinishlar:", attempts, "| xato:", err)

	fail[q] = &PgError{"40001"}
	fmt.Println(withRetry(3, func() error { _, err := db.Exec(q); return err }))
}

