var ErrNoAccount = errors.New("hisob topilmadi")

func debit(db *sql.DB, id, amount int) error {
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	var balance int
	err = tx.QueryRow("SELECT balance FROM accounts WHERE id = ? FOR UPDATE", id).Scan(&balance)
	if errors.Is(err, sql.ErrNoRows) {
		return ErrNoAccount
	}
	if err != nil {
		return err
	}
	_, err = tx.Exec("UPDATE accounts SET balance = ? WHERE id = ?", balance-amount, id)
	if err != nil {
		return err
	}
	return tx.Commit()
}

