	"fmt"

	"github.com/go-sql-driver/mysql"
	"github.com/jackc/pgx/v5/pgconn"
)

func isRetryable(err error) bool {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		switch pgErr.Code {
		case "40001", "40P01": // serialization_failure, deadlock_detected
			return true
		}
	}
	var myErr *mysql.MySQLError
	if errors.As(err, &myErr) {
		return myErr.Number == 1213 || myErr.Number == 1205 // deadlock, lock wait timeout
	}
	return false
}

func main() {
	fmt.Println(isRetryable(&pgconn.PgError{Code: "40001"}))
	fmt.Println(isRetryable(&pgconn.PgError{Code: "23505"})) // unique_violation
	fmt.Println(isRetryable(&mysql.MySQLError{Number: 1213}))
}

