var sortable = map[string]bool{"name": true, "age": true, "created_at": true}

func (q Query) Sort(param string) Query {
	dir, col := "ASC", param
	if strings.HasPrefix(param, "-") {
		dir, col = "DESC", param[1:]
	}
	if !sortable[col] {
		col = "id" // noma'lum ustun -> standart
	}
	q.tail += " ORDER BY " + col + " " + dir
	return q
}

func (q Query) Page(page, size int) Query {
	q.tail += fmt.Sprintf(" LIMIT %d OFFSET %d", size, (page-1)*size)
	return q
}

func main() {
	base := Select("id", "name").From("users")
	for _, p := range []string{"name", "-age", "password; DROP TABLE users"} {
		sql, _ := base.Sort(p).Page(2, 20).Build()
		fmt.Println(sql)
	}
}

