// Diqqat: satr literallari ichidagi '?' ni ajratmaydi (sqlx.Rebind ham shunday).
func rebind(query string) string {
	var sb strings.Builder
	n := 0
	for _, r := range query {
		if r == '?' {
			n++
			sb.WriteString("$" + strconv.Itoa(n))
			continue
		}
		sb.WriteRune(r)
	}
	return sb.String()
}

func main() {
	fmt.Println(rebind("SELECT * FROM users WHERE city = ? AND age >= ? LIMIT ?"))
}

