import (
	"fmt"
	"reflect"
	"strings"
)

func expandIn(query string, args ...any) (string, []any) {
	var out strings.Builder
	var flat []any
	i := 0
	for _, r := range query {
		if r != '?' {
			out.WriteRune(r)
			continue
		}
		v := reflect.ValueOf(args[i])
		i++
		if v.Kind() != reflect.Slice {
			out.WriteString("?")
			flat = append(flat, v.Interface())
			continue
		}
		out.WriteString(strings.TrimSuffix(strings.Repeat("?, ", v.Len()), ", "))
		for j := range v.Len() {
			flat = append(flat, v.Index(j).Interface())
		}
	}
	return out.String(), flat
}

func main() {
	sql, args := expandIn("SELECT * FROM users WHERE city = ? AND id IN (?)", "Toshkent", []int{4, 8, 15})
	fmt.Println(sql)
	fmt.Println(args)
}

