type Query struct {
	cols, joins, where []string
	table, tail        string
	args               []any
}

func Select(cols ...string) Query       { return Query{cols: cols} }
func (q Query) From(table string) Query { q.table = table; return q }

func (q Query) Where(cond string, args ...any) Query {
	q.where = append(slices.Clone(q.where), cond) // nusxa: asl so'rov o'zgarmaydi
	q.args = append(slices.Clone(q.args), args...)
	return q
}

func (q Query) Build() (string, []any) {
	s := "SELECT " + strings.Join(q.cols, ", ") + " FROM " + q.table
	for _, j := range q.joins {
		s += " " + j
	}
	if len(q.where) > 0 {
		s += " WHERE " + strings.Join(q.where, " AND ")
	}
	return s + q.tail, q.args
}

