func queryAll[T any](db *sql.DB, scan func(*sql.Rows) (T, error), q string, args ...any) ([]T, error) {
	rows, err := db.Query(q, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []T
	for rows.Next() {
		v, err := scan(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, rows.Err()
}

func main() {
	db, _ := sql.Open("fake", "")
	data["SELECT name FROM users"] = fake{cols: []string{"name"}, rows: [][]driver.Value{{"Aziz"}, {"Dilnoza"}}}
	data["SELECT id FROM users"] = fake{cols: []string{"id"}, rows: [][]driver.Value{{int64(1)}, {int64(2)}}}

	names, _ := queryAll(db, func(r *sql.Rows) (string, error) {
		var s string
		return s, r.Scan(&s)
	}, "SELECT name FROM users")
	ids, _ := queryAll(db, func(r *sql.Rows) (int, error) {
		var n int
		return n, r.Scan(&n)
	}, "SELECT id FROM users")
	fmt.Println(names, ids)
}

