type User struct {
	ID   int    `db:"id"`
	Name string `db:"name"`
}

func scanStruct(rows *sql.Rows, dest any) error {
	cols, _ := rows.Columns()
	v := reflect.ValueOf(dest).Elem()
	index := map[string]int{}
	for i := range v.NumField() {
		index[v.Type().Field(i).Tag.Get("db")] = i
	}
	ptrs := make([]any, len(cols))
	for i, c := range cols {
		idx, ok := index[c]
		if !ok {
			return fmt.Errorf("%q ustuniga mos maydon yo'q", c)
		}
		ptrs[i] = v.Field(idx).Addr().Interface()
	}
	return rows.Scan(ptrs...)
}

func main() {
	db, _ := sql.Open("fake", "")
	for _, cols := range [][]string{{"name", "id"}, {"id", "email"}} {
		q := "SELECT " + cols[0] + ", " + cols[1] + " FROM users"
		data[q] = fake{cols: cols, rows: [][]driver.Value{{"Aziz", int64(1)}}}
		rows, _ := db.Query(q)
		rows.Next()
		var u User
		fmt.Println(scanStruct(rows, &u), u)
		rows.Close()
	}
}

