	"regexp"
)

var namedRe = regexp.MustCompile(`:(\w+)`)

func bindNamed(query string, params map[string]any) (string, []any, error) {
	var args []any
	var missing []string
	out := namedRe.ReplaceAllStringFunc(query, func(m string) string {
		v, ok := params[m[1:]]
		if !ok {
			missing = append(missing, m[1:])
			return m
		}
		args = append(args, v)
		return "?"
	})
	if len(missing) > 0 {
		return "", nil, fmt.Errorf("parametr berilmagan: %v", missing)
	}
	return out, args, nil
}

func main() {
	q := "INSERT INTO users (name, email) VALUES (:name, :email)"
	sql, args, err := bindNamed(q, map[string]any{"name": "Aziz", "email": "aziz@mail.uz"})
	fmt.Println(sql, args, err)

	_, _, err = bindNamed(q, map[string]any{"name": "Aziz"})
	fmt.Println(err)
}

