type Migration struct {
	Version int
	Name    string
}

func pending(db *sql.DB, all []Migration) ([]Migration, error) {
	rows, err := db.Query("SELECT version FROM schema_migrations")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	applied := map[int]bool{}
	for rows.Next() {
		var v int
		if err := rows.Scan(&v); err != nil {
			return nil, err
		}
		applied[v] = true
	}
	var todo []Migration
	for _, m := range all {
		if !applied[m.Version] {
			todo = append(todo, m)
		}
	}
	return todo, rows.Err()
}

func main() {
	db, _ := sql.Open("fake", "")
	data["SELECT version FROM schema_migrations"] = fake{cols: []string{"version"}, rows: [][]driver.Value{{int64(1)}, {int64(2)}}}

	all := []Migration{{1, "create_users"}, {2, "add_email"}, {3, "add_phone"}}
	fmt.Println(pending(db, all))
}

