// Soxta drayver (faqat buyruqlar va tranzaksiya): Driver, Conn, Stmt va Tx — bitta tip.
type fake struct{ q string }

var (
	fail  = map[string]error{} // so'rov -> qaytariladigan xato
	calls []string             // bajarilgan buyruqlar jurnali
)

func init()                                               { sql.Register("fake", &fake{}) }
func (f *fake) Open(string) (driver.Conn, error)          { return &fake{}, nil }
func (f *fake) Prepare(q string) (driver.Stmt, error)     { return &fake{q}, nil }
func (f *fake) Close() error                              { return nil }
func (f *fake) NumInput() int                             { return -1 }
func (f *fake) Begin() (driver.Tx, error)                 { calls = append(calls, "BEGIN"); return f, nil }
func (f *fake) Commit() error                             { calls = append(calls, "COMMIT"); return nil }
func (f *fake) Rollback() error                           { calls = append(calls, "ROLLBACK"); return nil }
func (f *fake) Query([]driver.Value) (driver.Rows, error) { return nil, driver.ErrSkip }
func (f *fake) Exec(a []driver.Value) (driver.Result, error) {
	calls = append(calls, fmt.Sprintf("%s %v", f.q, a))
	return driver.RowsAffected(1), fail[f.q]
}

func apply(db *sql.DB, version int, ddl string) error {
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.Exec(ddl); err != nil {
		return fmt.Errorf("migration %d: %w", version, err)
	}
	if _, err := tx.Exec("INSERT INTO schema_migrations(version) VALUES (?)", version); err != nil {
		return err
	}
	return tx.Commit()
}

func main() {
	db, _ := sql.Open("fake", "")
	bad := "ALTER TABLE users ADD COLUMN age"
	fail[bad] = fmt.Errorf("syntax error at end of input")

	fmt.Println(apply(db, 3, "ALTER TABLE users ADD COLUMN phone TEXT"))
	fmt.Println(apply(db, 4, bad))
	for _, c := range calls {
		fmt.Println(" ", c)
	}
}

