)

var fileRe = regexp.MustCompile(`^(\d+)_(.+)\.(up|down)\.sql$`)

type File struct {
	Version   int
	Name      string
	Direction string
}

func parse(name string) (File, error) {
	m := fileRe.FindStringSubmatch(name)
	if m == nil {
		return File{}, fmt.Errorf("%q migratsiya fayli nomiga o'xshamaydi", name)
	}
	v, _ := strconv.Atoi(m[1])
	return File{v, m[2], m[3]}, nil
}

func main() {
	for _, n := range []string{"000001_create_users.up.sql", "000002_add_email.down.sql", "notes.txt"} {
		fmt.Println(parse(n))
	}
}

