)

func checksum(sql string) string {
	sum := sha256.Sum256([]byte(sql))
	return fmt.Sprintf("%x", sum[:4]) // qisqartirilgan ko'rinish
}

func main() {
	original := "CREATE TABLE users (id BIGSERIAL PRIMARY KEY);"
	stored := checksum(original) // schema_migrations jadvalida saqlangan

	edited := "CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name TEXT);"
	fmt.Println("saqlangan:", stored)
	fmt.Println("o'zgarmagan fayl mos:", checksum(original) == stored)
	fmt.Println("tahrirlangan fayl mos:", checksum(edited) == stored)
}

