)

type Dialect func(n int) string

var (
	Question Dialect = func(int) string { return "?" }
	Dollar   Dialect = func(n int) string { return fmt.Sprintf("$%d", n) }
	At       Dialect = func(n int) string { return fmt.Sprintf("@p%d", n) }
)

func render(query string, d Dialect) string {
	n := 0
	for strings.Contains(query, "{?}") {
		n++
		query = strings.Replace(query, "{?}", d(n), 1)
	}
	return query
}

func main() {
	q := "SELECT * FROM users WHERE city = {?} AND age >= {?}"
	fmt.Println("MySQL/SQLite:", render(q, Question))
	fmt.Println("PostgreSQL:  ", render(q, Dollar))
	fmt.Println("SQL Server:  ", render(q, At))
}

