package main

import (
	"errors"
	"fmt"
	"strings"
)

type DB struct {
	sql   string
	Error error
}

func (d *DB) Where(cond string) *DB {
	if d.Error != nil {
		return d // oldingi xato bor: hech narsa qilmaymiz
	}
	if strings.Contains(cond, ";") {
		d.Error = errors.New("shartda ';' taqiqlangan")
		return d
	}
	d.sql += " WHERE " + cond
	return d
}

func (d *DB) Order(col string) *DB {
	if d.Error == nil {
		d.sql += " ORDER BY " + col
	}
	return d
}

func main() {
	ok := (&DB{sql: "SELECT * FROM users"}).Where("age > 18").Order("name")
	fmt.Println(ok.sql, "|", ok.Error)

	bad := (&DB{sql: "SELECT * FROM users"}).Where("1=1; DROP TABLE users").Order("name")
	fmt.Println(bad.sql, "|", bad.Error)
}

