import (
	"fmt"
	"reflect"
	"strings"
)

type User struct {
	ID    int    `db:"id,pk"`
	Name  string `db:"name"`
	Email string `db:"email"`
	Age   int    `db:"age"`
}

func insertSQL(table string, v any) (string, []any) {
	rv := reflect.ValueOf(v)
	var cols, marks []string
	var args []any
	for i := range rv.NumField() {
		tag := rv.Type().Field(i).Tag.Get("db")
		if strings.HasSuffix(tag, ",pk") {
			continue // id bazada avtomatik beriladi
		}
		cols = append(cols, tag)
		marks = append(marks, "?")
		args = append(args, rv.Field(i).Interface())
	}
	return fmt.Sprintf("INSERT INTO %s (%s) VALUES (%s)", table, strings.Join(cols, ", "), strings.Join(marks, ", ")), args
}

func main() {
	fmt.Println(insertSQL("users", User{Name: "Aziz", Email: "aziz@mail.uz", Age: 25}))
}

